//! A verifier for leanVM execution proofs that runs on a Ledger Nano S Plus: `no_std`, no allocation, and a few
//! tens of kilobytes of RAM, the proof streamed in as it is read ([`transcript::Source`]).
//!
//! A port of leanVM's portable verifier (`vendor/leanVM/crates/verifier`), walking the same protocol in the same
//! order; what changes is how it holds what it needs. The bytecode it verifies proofs of is compiled in
//! ([`program`], generated by `keccak-pow gen-ledger`).

#![no_std]

#[cfg(test)]
extern crate std;

pub mod bus;
pub mod bytecode;
pub mod field;
pub mod hash;
pub mod keccak;
#[rustfmt::skip] // generated (`keccak-pow --gen-ledger`), compared byte for byte by a test
pub mod program;
pub mod ring_switch;
pub mod tables;
pub mod transcript;
pub mod whir;

use bus::{BusTables, Point, Slot, build_layout, bus_and_tables};
use field::{E, ONE, ZERO};
use hash::Digest;
use keccak::verify_keccak;
use ring_switch::{RingWeight, ring_switch};
use tables::{
    BYTECODE_FINAL_COUNTERS, GLOBAL_COLUMN_BASES, KECCAK_OUT, MEMORY_0, MEMORY_FINAL_COUNTERS, N_COLUMNS, N_TABLES,
    OP_KECCAK, QKECCAK, TABLE_WIDTHS,
};
use transcript::{Source, Transcript, eq_eval};

/// The most coordinates a point has.
pub const MAX_POINT: usize = 30;

/// Why a proof was rejected.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum Error {
    DigestHalf = 1,
    MultilinearSize,
    NotPowerOfTwo,
    StreamExhausted,
    StreamNotConsumed,
    GrindingNonce,
    MerkleOpeningShape,
    MerkleRootMismatch,
    GkrLayer,
    BusCountZero,
    TableSumcheckTerminal,
    AnnouncedTableSizes,
    AnnouncedHighLimb,
    PcsInverseRate,
    CommittedSize,
    WhirShape,
    QueryCountLadder,
    WhirTerminal,
    KeccakProduct,
    KeccakLayer,
    KeccakOutputOpening,
    KeccakInputOpening,
    /// The proof's transport failed (the device's USB stream).
    Transport,
}

pub(crate) fn require(condition: bool, error: Error) -> Result<(), Error> {
    if condition { Ok(()) } else { Err(error) }
}

/// The point a stacked claim is made at.
#[derive(Clone, Copy)]
enum At {
    Memory,
    Bytecode,
    Table(usize),
    Public,
    KeccakOutput,
}

/// Every claim on a committed column, in the walk's order: its column and its point. The stacked opening batches
/// them by powers of one challenge, after the ring-switch claim.
fn each_claim(mut visit: impl FnMut(usize, At)) {
    for column in [MEMORY_0, MEMORY_0 + 1, MEMORY_0 + 2, MEMORY_FINAL_COUNTERS] {
        visit(column, At::Memory);
    }
    visit(BYTECODE_FINAL_COUNTERS, At::Bytecode);
    for t in 0..N_TABLES {
        for local in 0..TABLE_WIDTHS[t] {
            visit(GLOBAL_COLUMN_BASES[t] + local, At::Table(t));
        }
    }
    for limb in 0..3 {
        visit(MEMORY_0 + limb, At::Public);
    }
    visit(QKECCAK, At::KeccakOutput);
}

/// What the stacked opening needs of the walk before it: the batched target, and every claim's weight at WHIR's
/// terminal point.
struct Stacked {
    root: Digest,
    log_inverse_rate: usize,
    stack_log: usize,
    placed: u64,
    slots: [Slot; N_COLUMNS],
    target: E,
    scale: E,
    bus_point: Point,
    log_memory: usize,
    log_bytecode: usize,
    table_point: Point,
    heights: [usize; N_TABLES],
    public_challenge: E,
    keccak_output: Point,
    ring_weight: RingWeight,
}

impl Stacked {
    /// `eq(point, x)` for the point `at` names, `x` as long as that point.
    fn eq_at(&self, at: At, x: &[E]) -> E {
        match at {
            At::Memory => eq_eval(&self.bus_point.as_slice()[..self.log_memory], x),
            At::Bytecode => eq_eval(&self.bus_point.as_slice()[..self.log_bytecode], x),
            At::Table(t) => eq_eval(&self.table_point.as_slice()[..self.heights[t]], x),
            At::Public => {
                // (challenge, 0, 0, ...).
                let mut product = ONE + self.public_challenge + x[0];
                for &value in &x[1..] {
                    product *= ONE + value;
                }
                product
            }
            At::KeccakOutput => eq_eval(self.keccak_output.as_slice(), x),
        }
    }

    /// Every claim's weight at the terminal point `x`, batched as the target is.
    fn basis(&self, x: &[E]) -> E {
        let qkeccak = self.slots[QKECCAK];
        let mut total = qkeccak.eq_above(x) * self.ring_weight.at(&x[..qkeccak.variables()]);
        // One eq product per point, then each claim's selector bits.
        let mut point_eq = [ZERO; N_TABLES + 4];
        let mut known = [false; N_TABLES + 4];
        let mut power = self.scale;
        each_claim(|column, at| {
            let slot = self.slots[column];
            if !slot.is_some() {
                return;
            }
            let i = match at {
                At::Memory => 0,
                At::Bytecode => 1,
                At::Public => 2,
                At::KeccakOutput => 3,
                At::Table(t) => 4 + t,
            };
            if !known[i] {
                point_eq[i] = self.eq_at(at, &x[..slot.variables()]);
                known[i] = true;
            }
            total += power * point_eq[i] * slot.eq_above(x);
            power *= self.scale;
        });
        total
    }
}

/// Verify a proof, read from `source`, that the compiled-in program runs on `public_input`.
pub fn verify<S: Source>(public_input: &[u8; 32], source: &mut S) -> Result<(), Error> {
    let public_input = Digest(*public_input);
    let mut transcript = Transcript::new(source, Digest(program::FIAT_SHAMIR_IV), public_input);
    let mut stacked = Stacked {
        root: Digest([0; 32]),
        log_inverse_rate: 0,
        stack_log: 0,
        placed: 0,
        slots: [Slot::NONE; N_COLUMNS],
        target: ZERO,
        scale: ZERO,
        bus_point: Point::EMPTY,
        log_memory: 0,
        log_bytecode: 0,
        table_point: Point::EMPTY,
        heights: [0; N_TABLES],
        public_challenge: ZERO,
        keccak_output: Point::EMPTY,
        ring_weight: RingWeight::ZERO,
    };
    walk(public_input, &mut transcript, &mut stacked)?;
    whir::verify_whir(
        &mut transcript,
        stacked.stack_log,
        stacked.placed,
        stacked.log_inverse_rate,
        stacked.target,
        stacked.root,
        |x| stacked.basis(x),
    )?;
    transcript.finish()
}

/// Everything before the stacked opening, into `stacked`. Out of line, so that its tables leave the stack
/// before WHIR runs.
#[inline(never)]
fn walk<S: Source>(public_input: Digest, transcript: &mut Transcript<S>, stacked: &mut Stacked) -> Result<(), Error> {
    // 1] The memory's log size, the table row counts, and the WHIR inverse rate.
    let mut announced = [ZERO; 2 + N_TABLES];
    transcript.next_scalars(&mut announced)?;
    require(
        announced.iter().all(|value| value.c1 == 0 && value.c2 == 0),
        Error::AnnouncedHighLimb,
    )?;
    let mut table_rows = [0u64; N_TABLES];
    for (rows, value) in table_rows.iter_mut().zip(&announced[1..1 + N_TABLES]) {
        *rows = value.c0;
    }
    let log_inverse_rate = announced[1 + N_TABLES].c0;
    require((1..=4).contains(&log_inverse_rate), Error::PcsInverseRate)?;
    let layout = build_layout(announced[0].c0, &table_rows, &mut stacked.slots)?;

    // 2] The WHIR commitment's Merkle root.
    let mut halves = [ZERO; 2];
    transcript.next_scalars(&mut halves)?;
    stacked.root = Digest::from_halves(halves[0], halves[1])?;

    // 3-4] The bus: one batched GKR over the push, pull and count trees; then the table sumcheck.
    let mut tables = BusTables::ZERO;
    bus_and_tables(&layout, transcript, &mut tables)?;

    // 5] The public input: each memory limb's claim is its public line at a challenge.
    let public_challenge = transcript.sample();
    let (first, second) = public_input.halves();
    let pairs = [(first.c0, second.c0), (first.c1, second.c1), (first.c2, second.c2)];
    let public_values = pairs.map(|(low, high)| {
        let (low, high) = (E::new(low, 0, 0), E::new(high, 0, 0));
        low + public_challenge * (low + high)
    });

    // 6] KECCAK, by GKR over the rounds; its output lanes' claims are the reduction's.
    let keccak_base = GLOBAL_COLUMN_BASES[OP_KECCAK];
    let mut slices = [ZERO; 64];
    let keccak_word = verify_keccak(
        transcript,
        layout.keccak,
        &tables.table_point.as_slice()[..layout.heights[OP_KECCAK]],
        &tables.values[keccak_base + KECCAK_OUT..keccak_base + KECCAK_OUT + 25],
        &mut stacked.keccak_output,
        &mut stacked.ring_weight.point,
        &mut slices,
    )?;

    // 7] Ring switching, then every claim on the stack batched into the opening's target.
    let ring_target = ring_switch(&slices, transcript, &mut stacked.ring_weight);
    let scale = transcript.sample();
    let mut target = ring_target;
    let mut power = scale;
    each_claim(|column, at| {
        if !stacked.slots[column].is_some() {
            return;
        }
        let value = match at {
            At::Memory if column == MEMORY_FINAL_COUNTERS => tables.memory_final,
            At::Memory => tables.memory[column - MEMORY_0],
            At::Bytecode => tables.bytecode_final,
            At::Table(_) => tables.values[column],
            At::Public => public_values[column - MEMORY_0],
            At::KeccakOutput => keccak_word,
        };
        target += power * value;
        power *= scale;
    });
    stacked.log_inverse_rate = log_inverse_rate as usize;
    stacked.stack_log = layout.stack_log;
    stacked.placed = layout.placed;
    stacked.target = target;
    stacked.scale = scale;
    stacked.bus_point = tables.bus_point;
    stacked.log_memory = layout.log_memory;
    stacked.log_bytecode = layout.log_bytecode;
    stacked.table_point = tables.table_point;
    stacked.heights = layout.heights;
    stacked.public_challenge = public_challenge;
    Ok(())
}
